import { conditionFields, conditionSources, connect, createNode, disconnect, initialEdges, initialNodes, memoryProposalsEnabled, parseTriggerInput, removeSchemaField, setMemoryProposals, setSchemaField, starterEdges, starterNodes, templates, updateIntegerConfig, type TriggerFieldType, type TriggerSchema, type WorkflowEdge, type WorkflowNode, type WorkflowNodeKind } from './workflow-model.js';
