  const fields: readonly [keyof typeof policy, string, number, number][] = [['milliseconds', 'Deadline (ms)', 1, 86400000], ['attempts', 'Attempts', 1, 5], ['tokens', 'Token limit', 0, 100000], ['cost', 'Cost limit', 0, 1000], ['toolRounds', 'Tool rounds', 0, 20], ['effects', 'External effects', 0, 20]];
  return <><strong>Node policy</strong>{fields.map(([key, label, min, max]) => <Field key={key} label={label}><input type="number" min={min} max={max} step={key === 'cost' ? 'any' : '1'} value={policy[key]} onChange={(event) => { const value = Number(event.target.value); if (Number.isFinite(value) && value >= min && value <= max && (key === 'cost' || Number.isSafeInteger(value))) update({ ...policy, [key]: value }); }} /></Field>)}</>;
