function TriggerField({ name, type, required, save, remove }: { name: string; type: TriggerFieldType; required: boolean; save: (name: string, type: TriggerFieldType, required: boolean) => void; remove: () => void }) {
  const [nextName, setNextName] = useState(name); const [nextType, setNextType] = useState(type); const [nextRequired, setNextRequired] = useState(required);
  return <div className="trigger-field"><input aria-label={`${name} name`} value={nextName} onChange={(event) => setNextName(event.target.value)} onBlur={() => save(nextName, nextType, nextRequired)} /><select aria-label={`${name} type`} value={nextType} onChange={(event) => { const value = event.target.value as TriggerFieldType; setNextType(value); save(nextName, value, nextRequired); }}><option value="string">Text</option><option value="number">Number</option><option value="boolean">True or false</option><option value="object">Object</option><option value="array">List</option></select><label><input type="checkbox" checked={nextRequired} onChange={(event) => { setNextRequired(event.target.checked); save(nextName, nextType, event.target.checked); }} /> Required</label><button type="button" onClick={remove}>Remove</button></div>;
}
function Harness({ model, setModel, maxSteps, setMaxSteps, onSave }: { model: string; setModel: (model: string) => void; maxSteps: number; setMaxSteps: (value: number) => void; onSave: () => void }) { return <section className="studio-pane"><div className="pane-heading"><div><p>Runtime configuration</p><h2>Harness</h2><span>Controls that apply to the bounded agent runtime.</span></div><button className="button" onClick={onSave}>Save revision</button></div><div className="pane-grid"><Field label="Primary model"><select value={model} onChange={(event) => setModel(event.target.value)}><option>Atlas 2.1</option><option>Compact 1.4</option></select></Field><Field label="Fallback model"><select defaultValue="compact"><option value="compact">Compact 1.4</option><option value="none">No fallback</option></select></Field><Field label="Team token budget"><input type="number" defaultValue="18000" min="1" /></Field><Field label="Maximum workflow steps"><input type="number" value={maxSteps} onChange={(event) => setMaxSteps(Math.max(1, Number(event.target.value) || 1))} min="1" /></Field></div><div className="harness-section"><h3>Capability boundaries</h3><div className="attached-grid"><AttachedItem name="Customer data" type="Read scoped account records" /><AttachedItem name="Billing actions" type="Requires human approval" /><AttachedItem name="Policy retrieval" type="Cited knowledge scope" /></div></div></section>; }
function Evaluations({ evaluated, run }: { evaluated: boolean; run: () => void }) { return <section className="studio-pane"><div className="pane-heading"><div><p>Release evidence</p><h2>Evaluations</h2><span>Checks and fixture simulations are recorded against a saved revision.</span></div><button className="button" onClick={run}>{evaluated ? 'Run again' : 'Run evaluation'}</button></div><div className="evaluation-list"><article><strong>Static draft checks</strong><span>Workflow references, declared capabilities, finite budgets</span><b>Ready</b></article><article><strong>Fixture simulation</strong><span>Runs the bounded workflow without dispatching a live provider</span><b>{evaluated ? 'Recorded' : 'Ready'}</b></article><article><strong>Release gate</strong><span>Live provider certification is required before publication</span><b className="blocked">Blocked</b></article></div></section>; }
function Versions({ revision, nodes, edges, onSave }: { revision: number; nodes: readonly WorkflowNode[]; edges: readonly WorkflowEdge[]; onSave: () => void }) { return <section className="studio-pane"><div className="pane-heading"><div><p>Governed history</p><h2>Versions</h2><span>Each saved revision is the unit sent to checks, evaluation, and review.</span></div><button className="button" onClick={onSave}>Save revision</button></div><div className="version-summary"><strong>Draft r{revision}</strong><span>{nodes.length} steps</span><span>{edges.length} connections</span><span>Ready for server validation</span></div><div className="evaluation-list"><article><strong>r{revision}</strong><span>Current local draft</span><b>Draft</b></article><article><strong>r{Math.max(1, revision - 1)}</strong><span>Prior saved configuration</span><b>Superseded</b></article></div></section>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }
function AttachedItem({ name, type }: { name: string; type: string }) { return <div className="attached-item"><i /><span><strong>{name}</strong><small>{type}</small></span><button>•••</button></div>; }

function Governance({ role, setRole, navigate }: { role: Role; setRole: (role: Role) => void; navigate: (route: Route) => void }) {
  const [period, setPeriod] = useState('7 days'); const [trace, setTrace] = useState<string>();
  if (role === 'operator') return <AccessBoundary setRole={setRole} navigate={navigate} />;
  return <section className="governance-shell"><div className="governance-heading"><div><p>Governance</p><h1>Operational overview</h1><span>Fixture preview · No live metrics</span></div><div className="governance-controls"><select aria-label="Time period" value={period} onChange={event => setPeriod(event.target.value)}><option>24 hours</option><option>7 days</option><option>30 days</option></select><button className="button-secondary">Export report</button><RoleSwitch role={role} setRole={setRole} /></div></div><div className="health-banner"><span><i /> Example data only</span><small>No live service status connected</small></div><div className="metrics-row"><Metric label="Workflow runs" value="3,463" change="+12.6%" note={`vs previous ${period}`} /><Metric label="Success rate" value="97.4%" change="+1.8%" note="within target" /><Metric label="Median latency" value="2.8s" change="−0.4s" note="faster than baseline" /><Metric label="Model spend" value="$53.11" change="+6.2%" note={`across ${period}`} warning /></div><div className="governance-grid"><article className="governance-card usage-card"><div className="card-heading"><div><h2>Runs and reliability</h2><p>Completed runs by day</p></div><span className="legend"><i /> Successful <i /> Failed</span></div><div className="usage-chart" aria-label="Workflow runs bar chart">{[62,76,68,88,72,94,84].map((height,index) => <div key={index}><span style={{ height: `${height}%` }} /><i style={{ height: `${Math.max(4, 15-index)}%` }} /><small>{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][index]}</small></div>)}</div></article><article className="governance-card service-card"><div className="card-heading"><div><h2>Service health</h2><p>Dependencies in the last 15 min</p></div><button>Open Grafana ↗</button></div>{[['Agent gateway','99.98%','148 ms'],['MCP bridge','99.91%','231 ms'],['Trace collector','100%','42 ms'],['Policy engine','99.96%','87 ms']].map(([name,uptime,latency]) => <div className="service-row" key={name}><i /><strong>{name}</strong><span>{uptime}</span><small>{latency}</small></div>)}</article><article className="governance-card workflows-card"><div className="card-heading"><div><h2>Workflow portfolio</h2><p>Usage and health by deployment</p></div><button>Filter <span>⌄</span></button></div><div className="data-table" role="table"><div className="table-head" role="row"><span>Workflow</span><span>Status</span><span>Runs</span><span>P95</span><span>Spend</span></div>{traces.map(item => <button className="table-row" role="row" key={item.name} onClick={() => setTrace(item.name)}><span><i>{item.name.slice(0,2).toUpperCase()}</i><strong>{item.name}</strong></span><span className={item.status === 'Healthy' ? 'status-ok' : 'status-warn'}><i />{item.status}</span><span>{item.runs}</span><span>{item.p95}</span><span>{item.cost}</span></button>)}</div></article><article className="governance-card team-card"><div className="card-heading"><div><h2>Team access</h2><p>8 members · 3 roles</p></div><button>Manage</button></div>{[['AK','Anika Kapoor','Admin','Active now'],['JM','Jonas Meyer','Builder','12 min ago'],['SM','Sofia Martins','Operator','1 hour ago']].map(([initials,name,memberRole,seen]) => <div className="member-row" key={name}><i>{initials}</i><span><strong>{name}</strong><small>{seen}</small></span><b>{memberRole}</b></div>)}</article></div>{trace && <TraceDrawer name={trace} close={() => setTrace(undefined)} />}</section>;
}
function Metric({ label, value, change, note, warning = false }: { label: string; value: string; change: string; note: string; warning?: boolean }) { return <article className="metric"><span>{label}</span><strong>{value}</strong><small className={warning ? 'metric-warning' : ''}>{change}</small><p>{note}</p></article>; }
function RoleSwitch({ role, setRole }: { role: Role; setRole: (role: Role) => void }) { return <label className="role-switch">Preview as<select value={role} onChange={event => setRole(event.target.value as Role)}><option value="admin">Admin</option><option value="operator">Operator</option></select></label>; }
function AccessBoundary({ setRole, navigate }: { setRole: (role: Role) => void; navigate: (route: Route) => void }) { return <section className="access-boundary"><div className="boundary-mark"><i /><i /></div><p>Restricted workspace</p><h1>Governance is available to admins.</h1><span>Operators can view run status and results in Solution Studio. Usage, traces, team access, and service health stay restricted.</span><div><button className="button" onClick={() => navigate('studio')}>Return to studio</button><button className="button-secondary" onClick={() => setRole('admin')}>Preview as admin</button></div></section>; }
function TraceDrawer({ name, close }: { name: string; close: () => void }) { return <div className="drawer-backdrop" onMouseDown={event => event.target === event.currentTarget && close()}><aside className="trace-drawer"><div className="drawer-heading"><div><small>Trace detail</small><h2>{name}</h2><span>run_8f2c1a7 · completed</span></div><button onClick={close} aria-label="Close trace">×</button></div><div className="trace-summary"><span><small>Duration</small><strong>2.71s</strong></span><span><small>Steps</small><strong>5</strong></span><span><small>Cost</small><strong>$0.041</strong></span></div><div className="trace-waterfall">{[['Webhook received','18ms'],['Triage request','742ms'],['Find account context','386ms'],['Plan resolution','1.2s'],['Apply account action','364ms']].map(([step,duration],index) => <div key={step}><i style={{ width: `${22+index*13}%`, marginLeft: `${index*6}%` }} /><span>{step}</span><small>{duration}</small></div>)}</div><section className="trace-log"><h3>Event log</h3><code>14:32:08.142&nbsp; context.resolved&nbsp;&nbsp; account: redacted</code><code>14:32:09.031&nbsp; policy.checked&nbsp;&nbsp;&nbsp; result: allow</code><code>14:32:10.489&nbsp; action.completed&nbsp; receipt: rcpt_92ad</code></section><button className="button-secondary drawer-action">Open in Grafana ↗</button></aside></div>; }

function SignIn({ authEnabled, navigate }: { authEnabled: boolean; navigate: (route: Route) => void }) {
  const [error, setError] = useState(''); const [submitted, setSubmitted] = useState(false);
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const email = String(new FormData(event.currentTarget).get('email') ?? ''); if (!email.includes('@')) { setError('Enter a valid work email.'); return; } setError(''); setSubmitted(true); window.setTimeout(() => navigate('studio'), 650); };
  return <section className="auth-page"><button className="auth-back" onClick={() => navigate('home')}>← Back to home</button><div className="auth-panel"><div className="auth-brand"><span className="brand-mark"><i /><i /><i /></span><strong>threadline</strong></div><h1>Welcome back.</h1><p>Sign in to continue to your workspace.</p>{!authEnabled && <form onSubmit={submit} noValidate><Field label="Work email"><input name="email" type="email" autoComplete="email" placeholder="you@company.com" aria-describedby={error ? 'email-error' : undefined} /></Field>{error && <span className="form-error" id="email-error">{error}</span>}<Field label="Password"><input name="password" type="password" autoComplete="current-password" placeholder="Enter your password" required /></Field><button className="button auth-submit" disabled={submitted}>{submitted ? 'Opening workspace…' : 'Continue'}</button></form>}<div className="auth-divider"><span>or</span></div>{authEnabled ? <SignInButton mode="modal" forceRedirectUrl="/studio"><button className="button-secondary auth-provider">Continue with Clerk</button></SignInButton> : <button className="button-secondary auth-provider" onClick={() => navigate('studio')}>Continue in demo mode</button>}<p className="auth-footnote">New to Threadline? {authEnabled ? <SignUpButton mode="modal"><button>Create an account</button></SignUpButton> : <button onClick={() => navigate('studio')}>Explore the demo</button>}</p></div><aside className="auth-aside"><blockquote>“We moved from scattered agent scripts to one operating picture in less than a week.”</blockquote><p><strong>Mara Okafor</strong><span>Head of Automation, Kestrel Works</span></p><div className="auth-grid-art"><i /><i /><i /><i /></div></aside></section>;
}
function Footer({ navigate }: { navigate: (route: Route) => void }) { return <footer className="footer page-shell"><button className="wordmark" onClick={() => navigate('home')}><span className="brand-mark"><i /><i /><i /></span><span>threadline</span></button><p>AI workflow infrastructure for teams that need proof, not promises.</p><nav><button onClick={() => navigate('studio')}>Studio</button><button onClick={() => navigate('governance')}>Governance</button><a href="/privacy">Privacy</a><a href="/terms">Terms</a></nav><small>© 2026 Threadline Systems</small></footer>; }
function routeFromPath(pathname: string): Route { if (pathname.startsWith('/studio')) return 'studio'; if (pathname.startsWith('/governance')) return 'governance'; if (pathname.startsWith('/sign-in')) return 'signin'; return 'home'; }
